{
 "what_you_observe": [
  "Tuesday, February 2. Seven pm.",
  "Phil plays the last eight bars until he can get through them.",
  "Rita said in the lobby: I don't speak to the crew. I push the door and go.",
  "Larry said in the lobby: To the crew, over my shoulder, not turning around: \"Taking the charge. Alma's got a girl in Pittsburgh and the place is going dark. You guys shoot the ballroom tonight, I'll be back.\"",
  "You are now at ballroom.",
  "There is time for one evening visit. The ballroom lights are on and the station line is open."
 ],
 "your_own_memories": [
  {
   "when": "last Tuesday afternoon",
   "witnessed": "Phil uses the paid ticket and rides the coach all the way to Pittsburgh.."
  },
  {
   "when": "last evening in Pittsburgh",
   "witnessed": "You reached your sister from the terminal payphone. She confirmed the van booking for Wednesday.",
   "your_words": "Hi, is the van driver still confirming for 8 AM tomorrow? I'm at the terminal now."
  },
  {
   "when": "this morning",
   "witnessed": "After that evening in Pittsburgh you woke back in your hotel bed. The radio again announced Tuesday, February 2."
  },
  {
   "what_you_did": "Phil plays the last eight bars until he can get through them.",
   "what_you_said": "You do not say anything to Rita or Larry. You nod at them — the small, tired nod of a man who has made up his mind and does not need them to follow. You set the coffee down. You walk. The ballroom door clicks shut behind you.",
   "your_intention": "Test the theory. Not the coach. Not the couch. The piano. If the loop is who I am and not where I am, then the afternoon I spend here is the variable I have not changed. I will be in Pittsburgh by morning. I will have the ticket. I will call the van driver again. But first: I sit down and I play, badly, and I stay until my fingers remember a shape I do not own."
  },
  "Phil plays the last eight bars until he can get through them.",
  "Rita said in the lobby: I don't speak to the crew. I push the door and go.",
  "Larry said in the lobby: To the crew, over my shoulder, not turning around: \"Taking the charge. Alma's got a girl in Pittsburgh and the place is going dark. You guys shoot the ballroom tonight, I'll be back.\"",
  "You are now at ballroom."
 ],
 "who_you_are_with": "your present location",
 "physical_choices": {
  "play_piano": "Play at the ballroom, whether anyone comes or not.",
  "go_to_party": "Attend the party and see who else comes.",
  "ask_Rita_to_dance": "Go to the ballroom and offer Rita a dance. Her choice determines whether she is there and available.",
  "wait_at_Rialto": "Spend the evening at the Rialto booth.",
  "go_to_bed": "Go upstairs alone and let the evening go by.",
  "sit_at_depot": "Let the evening go by on the empty depot bench."
 }
}
